package com.tallerzapata.backend.infrastructure.persistence.recovery;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="recupero_obligacion_pago_aplicaciones") public class FranchiseRecoveryClientObligationPaymentApplicationEntity {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="obligacion_id") private Long obligationId; @Column(name="movimiento_id") private Long movementId; @Column(name="monto_aplicado") private BigDecimal appliedAmount; @Column(name="idempotency_key") private String idempotencyKey; @Column(name="estado_codigo") private String statusCode; @Column(name="revierte_aplicacion_id") private Long reversedApplicationId; @Column(name="created_at") private LocalDateTime createdAt; @Column(name="annulled_at") private LocalDateTime annulledAt;
 public Long getId(){return id;} public Long getObligationId(){return obligationId;} public void setObligationId(Long v){obligationId=v;} public Long getMovementId(){return movementId;} public void setMovementId(Long v){movementId=v;} public BigDecimal getAppliedAmount(){return appliedAmount;} public void setAppliedAmount(BigDecimal v){appliedAmount=v;} public String getIdempotencyKey(){return idempotencyKey;} public void setIdempotencyKey(String v){idempotencyKey=v;} public String getStatusCode(){return statusCode;} public void setStatusCode(String v){statusCode=v;} public Long getReversedApplicationId(){return reversedApplicationId;} public void setReversedApplicationId(Long v){reversedApplicationId=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;} public LocalDateTime getAnnulledAt(){return annulledAt;} public void setAnnulledAt(LocalDateTime v){annulledAt=v;}
}
